SELECT 



        AND l.order_no LIKE CONCAT('%', #{q.orderNo}, '%')


        AND l.biz_type = #{q.bizType}


        AND l.status = #{q.status}


        AND (g.goods_code LIKE CONCAT('%', #{q.goodsKeyword}, '%')
             OR g.barcode LIKE CONCAT('%', #{q.goodsKeyword}, '%')
             OR g.name LIKE CONCAT('%', #{q.goodsKeyword}, '%'))


        AND l.apply_name LIKE CONCAT('%', #{q.applyName}, '%')


        AND l.create_time >= #{beginTime}


        AND l.create_time < #{endTime}


ORDER BY l.create_time DESC, l.id DESC
